import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    my_score = 0
    op_score = 0
    opp_def = 0
    for a, b in history:
        if a == 'C':
            if b == 'C':
                my_score += 3
                op_score += 3
            else:
                op_score += 5
                opp_def += 1
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                op_score += 1
                opp_def += 1

    last_my, last_op = history[-1]

    # Detect long runs at the tail
    tail_op_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            tail_op_d += 1
        else:
            break
    tail_op_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            tail_op_c += 1
        else:
            break

    remaining = 100 - n

    # Archive-aware: if opponent has never defected, cooperate but milk the end.
    if opp_def == 0:
        if remaining <= 3 and rng.random() < 0.85:
            return 'D'
        return 'C'

    # If opponent always defects, defect.
    if opp_def == n:
        return 'D'

    # If opponent is in a long defection streak, defect hard but occasionally test.
    if tail_op_d >= 3:
        if tail_op_d % 5 == 0 and rng.random() < 0.5:
            return 'C'
        return 'D'

    # Forgiving tit-for-tat when opponent just defected once.
    if last_op == 'D':
        if tail_op_d == 1 and op_score - my_score < 6:
            # Single isolated defection: punish once, then return to C if they reciprocate.
            if last_my == 'D':
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round.
    recent = op[-12:] if n >= 12 else op
    recent_def = recent.count('D')

    # If opponent has been mostly cooperative recently, stay cooperative.
    if recent_def <= 1:
        # Late-game opportunistic defection against pure cooperators.
        if remaining <= 2 and tail_op_c >= 6:
            return 'D'
        return 'C'

    # Moderate defection rate: cooperate to sustain mutual benefit but probe.
    if recent_def <= 3:
        if last_my == 'D' and rng.random() < 0.7:
            return 'C'
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # High recent defection rate: punish mostly, occasionally offer an olive branch.
    if rng.random() < 0.2:
        return 'C'
    return 'D'
